<script>
document.addEventListener('DOMContentLoaded', () => {
    const reportData = @json($chartData);
    const charts = [];
    const pesos = value => '₱' + Number(value).toLocaleString('en-PH', {maximumFractionDigits:2});
    const labels = reportData.trend.map(p => p.period);
    const base = {responsive:true, maintainAspectRatio:false, animation:false, plugins:{legend:{labels:{boxWidth:9,font:{size:10}}}}, scales:{x:{grid:{display:false},ticks:{font:{size:9},maxTicksLimit:6}},y:{beginAtZero:true,ticks:{font:{size:9}}}}};
    charts.push(new window.Chart(document.getElementById('incomeTrend'), {type:'line',data:{labels,datasets:[{label:'Billing',data:reportData.trend.map(p=>p.billing/100),borderColor:'#2563eb',backgroundColor:'#2563eb',pointRadius:2,tension:0.3},{label:'Collections',data:reportData.trend.map(p=>p.collections/100),borderColor:'#55a630',backgroundColor:'#55a630',pointRadius:2,tension:0.3}]},options:{...base,plugins:{...base.plugins,tooltip:{callbacks:{label:ctx=>ctx.dataset.label+': '+pesos(ctx.parsed.y)}}},scales:{...base.scales,y:{...base.scales.y,ticks:{...base.scales.y.ticks,callback:v=>pesos(v)}}}}}));
    charts.push(new window.Chart(document.getElementById('collectionRate'), {type:'line',data:{labels,datasets:[{label:'Collection Rate',data:reportData.trend.map(p=>p.rate),borderColor:'#55a630',backgroundColor:'rgba(85,166,48,.10)',fill:true,pointRadius:2,tension:0.3}]},options:{...base,plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>Number(ctx.parsed.y).toFixed(2)+'%'}}},scales:{...base.scales,y:{min:0,max:100,ticks:{font:{size:9},callback:v=>v+'%'}}}}}));
    const center = {id:'reportCenter',afterDraw(chart){const {ctx,chartArea}=chart;if(!chartArea)return;const x=(chartArea.left+chartArea.right)/2,y=(chartArea.top+chartArea.bottom)/2;ctx.save();ctx.textAlign='center';ctx.fillStyle='#17345f';ctx.font='bold 13px sans-serif';ctx.fillText(chart.options.plugins.reportCenter.text,x,y);ctx.font='10px sans-serif';ctx.fillText('Total',x,y+16);ctx.restore();}};
    const donut = (id,values,colors,total,isMoney) => {
        const empty = Object.values(values).every(v=>v===0);
        charts.push(new window.Chart(document.getElementById(id), {
            type:'doughnut',
            plugins:[center],
            data:{
                labels:empty ? ['No data'] : Object.keys(values),
                datasets:[{data:empty ? [1] : Object.values(values).map(v=>isMoney?v/100:v), backgroundColor:empty?['#e2e8f0']:colors, borderWidth:1}]
            },
            options:{
                responsive:true, maintainAspectRatio:false, animation:false, cutout:'67%',
                plugins:{
                    reportCenter:{text:isMoney?pesos(total/100):String(total)},
                    legend:{position:'bottom',labels:{boxWidth:8,font:{size:9}}},
                    tooltip:{enabled:!empty,callbacks:{label:ctx=>ctx.label+': '+(isMoney?pesos(ctx.parsed):ctx.parsed+' rooms')}}
                }
            }
        }));
    };
    donut('agingChart',reportData.aging,['#55a630','#f5bc00','#ff9100','#d66b78','#c62637'],reportData.outstanding,true);
    donut('unitChart',reportData.units,['#2563eb','#55a630','#7754b7'],reportData.totalUnits,false);
    document.getElementById('printReports').addEventListener('click',()=>window.print());
    window.addEventListener('beforeprint',()=>charts.forEach(chart=>chart.resize()));
    window.addEventListener('afterprint',()=>charts.forEach(chart=>chart.resize()));
});
</script>
@endpush
